}

.no-sub-work-view {
  margin-top: var(--header-height);
  padding-top: fluid(64, 128);
  padding-bottom: fluid(64, 128);

  &__inner {
    display: flex;
    flex-direction: column;
    padding-top: var(--gutter-lg);
  }
  .no-view-more {
    text-align: center;
    margin-top: var(--gutter-2xl);
    .no-corner-btn-wrap {
      justify-content: center;
    }
  }

  &__head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--gutter-md);
    padding-top: var(--gutter-lg);
    border-top: 1px solid var(--clr-border-default);
  }

  &__title {
    color: var(--clr-text-title);
    @include font("f-display-2");
    font-weight: 700;
  }

  &__award {
    display: inline-flex;
    align-items: center;
    gap: var(--gutter-xs);
    color: var(--clr-text-body);
    @include font("f-body-2");

    img {
      width: fluid(20, 36);
      height: fluid(20, 36);
      object-fit: contain;
      flex-shrink: 0;
    }

    span {
      font-family: var(--family-en-title);
      @include font("f-body-3");
    }
  }
  .no-corner-btn-wrap {
    display: flex;
    justify-content: flex-end;
  }

  &__info {
    margin-top: var(--gutter-2xl);
    display: grid;
    grid-template-columns: 10fr 2fr;
    gap: var(--gutter-md);

    &-list {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: var(--gutter-sm);
    }

    &-item {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-sm);
    }

    &-label {
      color: var(--clr-text-body);
      font-family: var(--family-ui);
      @include font("f-body-3");
    }

    &-value {
      color: var(--clr-text-title);
      @include font("f-body-1");
    }

    &-sub-list {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-2xs);
    }

    &-sub-text {
      color: var(--clr-text-title);
      @include font("f-body-1");
    }

    .no-sub-work-view__button {
      align-self: flex-start;
      min-width: fluid(152, 188);
    }
  }

  &__thumbnail {
    position: relative;
    overflow: hidden;
    isolation: isolate;
    border: 1px solid var(--clr-border-default);
    padding: var(--gutter-xs);
    margin-top: var(--gutter-2xl);

    video,
    img {
      width: 100%;
      aspect-ratio: 16/9;
      display: block;
      object-fit: cover;
      position: relative;
      z-index: 1;
    }
  }

  &__content {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    background: var(--clr-surface-default);
    border: 1px solid var(--clr-border-default);

    &-wrap {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-2xl);
    }

    &__overview {
      padding: var(--gutter-xl);
      gap: var(--gutter-lg);
      display: grid;
      grid-template-columns: 3fr 9fr;
    }

    &-title {
      color: var(--clr-text-title);
      @include font("f-heading-1");
    }

    &-description {
      color: var(--clr-text-body);
      @include font("f-body-3");
    }

    &__image {
      margin-top: var(--gutter-lg);

      img,
      video {
        width: 100%;
        display: block;
        object-fit: cover;
      }
    }
  }
}

@keyframes no-works-type {
  from {
    max-width: 0;
  }
  to {
    max-width: 11ch;
  }
}

@keyframes no-works-caret {
  0%,
  49% {
    border-right-color: var(--clr-text-desc);
  }
  50%,
  100% {
    border-right-color: transparent;
  }
}

