@use "../abstract" as *;

.no-ui-panel {
  position: fixed;
  bottom: 0;
  height: calc(100% - var(--header-height));
  width: 100%;
  z-index: var(--z-index-dropdown);
  pointer-events: none;

  &__container {
    position: relative;
    width: 100%;
    height: 100%;
  }

  &__inner {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: var(--gutter-2xs);
    box-sizing: border-box;
    opacity: 0;
    transition: opacity 0.28s var(--ease-default) 0.9s;
  }

  &.is-visible &__inner {
    opacity: 1;

