import { Device } from "../utils/Device.js";
import { Helpers } from "../utils/Helpers.js";
import { PerformanceProfile } from "../utils/PerformanceProfile.js";
import type {
  ResponsiveBreakpoint,
  ResponsiveEnvironmentInput,
  ResponsiveListener,
  ResponsiveSnapshot,
} from "../types/runtime.types.js";

const DEFAULT_VIEWPORT_WIDTH = 1440;
const DEFAULT_VIEWPORT_HEIGHT = 900;
const DEFAULT_DEVICE_PIXEL_RATIO = 1;

export class ResponsiveRuntime {
  private _snapshot: ResponsiveSnapshot | null = null;
  private _listeners = new Set<ResponsiveListener>();
  private _reduceMotionMedia: MediaQueryList | null = null;
  private _reduceMotionHandler: (() => void) | null = null;
  private _initialized = false;

  init(): void {
    if (this._initialized) return;
    this._initialized = true;
    this.updateFromWindow();
    this._bindPreferenceListeners();
  }

  dispose(): void {
    if (this._reduceMotionMedia && this._reduceMotionHandler) {
      this._reduceMotionMedia.removeEventListener(
        "change",
        this._reduceMotionHandler,
      );
    }
    this._reduceMotionMedia = null;
    this._reduceMotionHandler = null;
    this._listeners.clear();
    this._initialized = false;
  }

  updateFromWindow(): Readonly<ResponsiveSnapshot> {
    const snapshot = this._createSnapshot();
    this._snapshot = snapshot;
    this._applyCssVariables(snapshot);
    this._listeners.forEach((listener) => listener(snapshot));
    return snapshot;
