.no-sub-work-view {
  margin-top: var(--header-height);
  padding-top: fluid(64, 128);
  padding-bottom: fluid(64, 128);

  &__inner {
    display: flex;
    flex-direction: column;
    padding-top: var(--gutter-lg);
    padding-bottom: fluid(72, 96);
  }

  &__sticky-bar {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    z-index: calc(var(--z-index-header) - 80);
    display: flex;
    justify-content: center;
    padding: var(--gutter-md) var(--gutter-container);
    background: color-mix(in srgb, var(--clr-surface-default) 88%, transparent);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border-top: 1px solid var(--clr-border-default);

    .no-view-more {
      margin: 0;

      .no-corner-btn-wrap {
        justify-content: center;
      }
    }
  }

  &__head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--gutter-md);
    padding-top: var(--gutter-lg);
    border-top: 1px solid var(--clr-border-default);
  }

  &__title {
    color: var(--clr-text-title);
    @include font("f-display-2");
    font-weight: 700;
  }

  &__award {
    display: inline-flex;
    align-items: center;
    gap: var(--gutter-xs);
    color: var(--clr-text-body);

